package com.fixmer.mared.technology.workspace.live122;
import com.fixmer.genesis.technology.workspace.live122.*;import net.minecraft.client.Minecraft;import net.neoforged.neoforge.network.PacketDistributor;import java.util.*;import java.util.function.Consumer;
/** Connection-pinned. Only exact idempotent CRDT batches are automatically retried. */
public final class WorkspaceClient122 {
 private final Object connection=Minecraft.getInstance().getConnection();private Map<String,String> pending;private Consumer<Map<String,String>> callback;private long sent;private boolean attached,suspended;private String actor,store;public String result="IDLE";private final Consumer<WorkspacePayloads122.Response> sink=p->Minecraft.getInstance().execute(()->receive(p));
 public void attach(){attached=true;WorkspacePayloads122.sink=sink;}public void detach(){attached=false;if(WorkspacePayloads122.sink==sink)WorkspacePayloads122.sink=p->{};pending=null;callback=null;}public boolean connected(){var c=Minecraft.getInstance().getConnection();return !suspended&&c!=null&&c==connection&&c.hasChannel(WorkspacePayloads122.Request.TYPE.id());}public boolean busy(){return pending!=null;}
 public void send(Map<String,String> q,Consumer<Map<String,String>> done){if(!attached||!connected()||busy()){result=connected()?"BUSY":"DISCONNECTED";return;}try{WorkspaceHub122.request(q);pending=Map.copyOf(q);callback=done;sent=System.nanoTime();result="WAITING";transmit();}catch(Exception e){pending=null;callback=null;result="INVALID";}}
 private void transmit()throws Exception{PacketDistributor.sendToServer(new WorkspacePayloads122.Request(WorkspaceCodec122.encode(pending,WorkspaceCodec122.REQUEST)));}
 public void tick(){if(pending==null)return;if(!connected()){pending=null;callback=null;result="DISCONNECTED";return;}if(System.nanoTime()-sent>3_000_000_000L){if(pending.get("op").equals("EDIT")){try{transmit();sent=System.nanoTime();result="RETRY";}catch(Exception e){result="DISCONNECTED";}}else{pending=null;callback=null;result="UNKNOWN";}}}
 private void receive(WorkspacePayloads122.Response p){if(!attached||!connected()||pending==null)return;try{var d=WorkspaceCodec122.decode(p.bytes(),WorkspaceCodec122.RESPONSE);if(!pending.get("request").equals(d.get("request")))return;if(d.getOrDefault("result","").equals("BUSY")&&pending.get("op").equals("EDIT")){sent=System.nanoTime()-2_500_000_000L;return;}if(d.containsKey("actor")){if(actor!=null&&!actor.equals(d.get("actor"))){suspended=true;pending=null;callback=null;result="IDENTITY_CHANGED";return;}actor=d.get("actor");}if(d.containsKey("store")){if(store!=null&&!store.equals(d.get("store"))){suspended=true;pending=null;callback=null;result="STORE_CHANGED";return;}store=d.get("store");}if(!pending.get("project").isEmpty()&&d.containsKey("project")&&!pending.get("project").equals(d.get("project")))throw new IllegalArgumentException("PROJECT");var done=callback;pending=null;callback=null;result=d.getOrDefault("result","INVALID");if(done!=null)done.accept(d);}catch(Exception e){pending=null;callback=null;result="INVALID";com.fixmer.mared.Mared.LOGGER.warn("[Workspace122] Rejected response",e);}}
 public static Map<String,String> request(String op,String project,Map<String,String> fields){var q=new TreeMap<>(fields);q.put("request",UUID.randomUUID().toString());q.put("op",op);q.put("project",project);return Map.copyOf(q);}
}
